<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionThemeVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;

trait ThemeVersionThemeAttributeHolder
{
    protected ThemeVersionThemeVO|ThemeRef|null $theme = null;
    protected bool $themeAssigned = false;

    public function getThemeOrCurrent(ThemeVersionThemeVO $theme): ThemeVersionThemeVO
    {
        if ($this->themeAssigned) {
            \assert(null !== $this->theme);
            return ThemeVersionThemeVO::from($this->theme);
        } else {
            return $theme;
        }
    }
    public function themeTryBuildInitial(ConstraintFailList $error): ?ThemeVersionThemeVO
    {
        return  ThemeVersionThemeVO::tryFrom($this->themeAssigned ? $this->theme : null, $error);
    }
    public function theme(ThemeVersionThemeVO|ThemeRef $theme): static
    {
        $this->theme = $theme;
        $this->themeAssigned = true;
        return $this;
    }
    public function getTheme(): ?ThemeRef
    {
        return $this->theme instanceof ThemeVersionThemeVO ? $this->theme->value() : $this->theme;
    }
    public function isThemeAssigned(): bool
    {
        return $this->themeAssigned;
    }
    public function writeThemeTo(mixed $att): void
    {
        if ($this->themeAssigned) {
            \assert(null !== $this->theme);
            $att->theme($this->theme);
        }
    }
    public function readThemeFrom(mixed $att): void
    {
        if ($att->isThemeAssigned()) {
            $theme = $att->getTheme();
            \assert(null !== $theme);
            $this->theme($theme);
        }
    }
    public function unsetTheme(): static
    {
        $this->themeAssigned = false;
        return $this;
    }
    protected function withDefaultTheme(): void
    {
    }
    protected function withAssertedThemeRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->themeAssigned = $this->themeAssigned) {
            $value->theme = ThemeVersionThemeVO::tryFrom($this->theme, $errorsList);
        }
    }
}
